<?php defined('ABSPATH') || exit;$d=$args['data'];if(!$d['gallery'])return; ?>
<section id="property-gallery" class="dossier-section"><div class="dossier-section-heading"><p class="dossier-eyebrow">IN PICTURES</p><h2>A closer look.</h2></div><div class="dossier-gallery"><?php foreach($d['gallery'] as $image):$index=array_search($image,$d['photos'],true); ?><a href="<?php echo esc_url(wp_get_attachment_url($image)); ?>" data-gallery-open="<?php echo (int)$index; ?>" aria-label="<?php echo esc_attr('Open photo '.($index+1).' of '.$d['title']); ?>"><?php echo wp_get_attachment_image($image,'large',false,array('loading'=>'lazy','sizes'=>'(max-width: 800px) 100vw, 50vw','alt'=>get_post_meta($image,'_wp_attachment_image_alt',true)?:$d['title'].' — property view '.($index+1))); ?><span aria-hidden="true">↗</span></a><?php endforeach; ?></div></section>
